m", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分步计算出错"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "抽取与放回的关键是\"有放回独立，无放回不独立\"。无放回时每次概率会变。"}]}]}]}$$ AS jsonb), NULL, '数量关系-概率问题-抽取与放回的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "概率问题", "抽取与放回"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_prob_draw", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
